"  let mut i: usize = 0;\n"
"  while i < len(parts) {\n"
"    __print_str(parts[i]);\n"
"    i += 1;\n"
"  }\n"
"}\n"
"\n"
"fn __fmt_eprint(parts: string...) {\n"
"  let mut i: usize = 0;\n"
"  while i < len(parts) {\n"
"    __eprint_str(parts[i]);\n"
"    i += 1;\n"
"  }\n"
"}\n"
"\n"
"fn __fmt_build(parts: string...) -> string {\n"
"  let mut n: usize = 0;\n"
"  let mut i: usize = 0;\n"
"  while i < len(parts) {\n"
"    n += len(parts[i]);\n"
"    i += 1;\n"
"  }\n"
"  let buf: []u8 = make([]u8, n);\n"
"  let mut o: usize = 0;\n"
"  i = 0;\n"
"  while i < len(parts) {\n"
"    let p: string = parts[i];\n"
"    let mut j: usize = 0;\n"
"    while j < len(p) {\n"
"      buf[o] = p[j];\n"
"      o += 1;\n"
"      j += 1;\n"
"    }\n"
"    i += 1;\n"
"  }\n"
"  return intrinsics.slice_string(buf);\n"
"}\n"
"// wasm32-wasi prelude tail: fd_write/proc_write imports, a bump allocator\n"
"// over the linear-memory heap, and the per-target hooks the core builds on.\n"
"\n"
"extern fn fd_write(fd: i32, iovs: i32, count: i32, nwritten: i32) -> i32;\n"
"\n"
"extern fn proc_exit(code: i32);\n"
"\n"
"extern fn system(cmd: *u8) -> i32;\n"
"\n"
"extern fn chmod(path: *u8, mode: i32) -> i32;\n"
"\n"
"struct Iov {\n"
"  p: i32,\n"
"  l: i32,\n"
"}\n"
"\n"
"// ---- allocator (0.4.2): size-bucket recycling over the bump heap --------\n"
"// SIX-CLASS interim version (fixed convention; no big-class recycling)\n"
"\n"
"static mut HEAP: usize = 65536;\n"
"\n"
"fn bump_big(n: usize) -> *u8 {\n"
"  let p: usize = HEAP;\n"
"  let mut end: usize = p + n;\n"
"  end = (end + 7) & 4294967288;\n"
"  if end > 4278190080 {\n"
"    __eprint_str(\"rho: wasm32 heap exhausted\\n\");\n"
"    __exit(101);\n"
"  }\n"
"  let cur: usize = intrinsics.mem_size() * 65536;\n"
"  if end > cur {\n"
"    let pages: usize = (end - cur + 65535) / 65536;\n"
"    if intrinsics.mem_grow(pages) == 4294967295 {\n"
"      __eprint_str(\"rho: out of linear memory\\n\");\n"
"      __exit(101);\n"
"    }\n"
"  }\n"
"  HEAP = end;\n"
"  return p as *u8;\n"
"}\n"
"\n"
"fn zero_bytes(from: usize, count: usize) {\n"
"  let mut k: usize = 0;\n"
"  while k + 8 <= count {\n"
"    intrinsics.store_u64((from + k) as *u8, 0);\n"
"    k += 8;\n"
"  }\n"
"  while k < count {\n"
"    intrinsics.store_u8((from + k) as *u8, 0);\n"
"    k += 1;\n"
"  }\n"
"}\n"
"\n"
"fn dead_mark() -> usize {\n"
"  return 6510615555426900570;\n"
"}\n"
"\n"
"static mut FL0: usize = 0;\n"
"static mut FL1: usize = 0;\n"
"static mut FL2: usize = 0;\n"
"static mut FL3: usize = 0;\n"
"static mut FL4: usize = 0;\n"
"static mut FL5: usize = 0;\n"
"static mut C0: usize = 0;\n"
"static mut E0: usize = 0;\n"
"static mut C1: usize = 0;\n"
"static mut E1: usize = 0;\n"
"static mut C2: usize = 0;\n"
"static mut E2: usize = 0;\n"
"static mut C3: usize = 0;\n"
"static mut E3: usize = 0;\n"
"static mut C4: usize = 0;\n"
"static mut E4: usize = 0;\n"
"static mut C5: usize = 0;\n"
"static mut E5: usize = 0;\n"
"static mut LO0: usize = 0;\n"
"static mut HI0: usize = 0;\n"
"static mut LO1: usize = 0;\n"
"static mut HI1: usize = 0;\n"
"static mut LO2: usize = 0;\n"
"static mut HI2: usize = 0;\n"
"static mut LO3: usize = 0;\n"
"static mut HI3: usize = 0;\n"
"static mut LO4: usize = 0;\n"
"static mut HI4: usize = 0;\n"
"static mut LO5: usize = 0;\n"
"static mut HI5: usize = 0;\n"
"\n"
"// chunk registry: every bucket chunk ever carved, as (base, end, class)\n"
"// triples in raw bump storage. The per-class LO/HI pair only covers the\n"
"// CURRENT chunk — without the registry, a block handed out from an older\n"
"// chunk fails the region test when it dies and leaks, the freelist\n"
"// starves, and a long compile grinds through chunks it never reuses (the\n"
"// emit-phase treadmill: freelists empty while the cursor climbs).\n"
"static mut CT: usize = 0;\n"
"static mut CTN: usize = 0;\n"
"static mut CTC: usize = 0;\n"
"\n"
"fn as_class_stride(k: usize) -> usize {\n"
"  if k == 0 { return 64; }\n"
"  if k == 1 { return 128; }\n"
"  if k == 2 { return 256; }\n"
"  if k == 3 { return 512; }\n"
"  if k == 4 { return 1024; }\n"
"  if k == 5 { return 4096; }\n"
"  if k < 16 {\n"
"    let mut s: usize = 8192;\n"
"    let mut j: usize = k - 6;\n"
"    while j > 0 {\n"
"      s = s * 2;\n"
"      j -= 1;\n"
"    }\n"
"    return s;\n"
"  }\n"
"  return 4096;\n"
"}\n"
"\n"
"// big classes 6..15 (strides 8K..4M): the emit phase's doubling buffers —\n"
"// out-buffers, text slabs, offs tables — all ride sizes past the six small\n"
"// strides; without recycling every grown-away intermediate leaks into the\n"
"// bump and a self-compile climbs past the wasm32 ceiling. One context\n"
"// block holds, per class: freelist head, chunk cursor, chunk end, chunk\n"
"// lo, chunk hi (10 classes x 5 slots x 8 bytes).\n"
"static mut BCX: usize = 0;\n"
"\n"
"fn bcx_ensure() {\n"
"  if BCX == 0 {\n"
"    BCX = bump_big(400) as usize;\n"
"    zero_bytes(BCX, 400);\n"
"  }\n"
"}\n"
"\n"
"fn big_class_of(n: usize) -> usize {\n"
"  let mut k: usize = 6;\n"
"  let mut stride: usize = 8192;\n"
"  while stride < n && k < 15 {\n"
"    stride = stride * 2;\n"
"    k += 1;\n"
"  }\n"
"  return k;\n"
"}\n"
"\n"
"fn as_note_chunk(base: usize, end_: usize, k: usize) {\n"
"  if CTN == CTC {\n"
"    let mut newcap: usize = 16;\n"
"    if CTC != 0 {\n"
"      newcap = CTC * 2;\n"
"    }\n"
"    let p: usize = bump_big(newcap * 24) as usize;\n"
"    let mut i: usize = 0;\n"
"    while i < CTN * 3 {\n"
"      intrinsics.store_u64((p + i * 8) as *u8,\n"
"                           intrinsics.load_u64((CT + i * 8) as *u8));\n"
"      i += 1;\n"
"    }\n"
"    CT = p;\n"
"    CTC = newcap;\n"
"  }\n"
"  intrinsics.store_u64((CT + CTN * 24) as *u8, base as u64);\n"
"  intrinsics.store_u64((CT + CTN * 24 + 8) as *u8, end_ as u64);\n"
"  intrinsics.store_u64((CT + CTN * 24 + 16) as *u8, k as u64);\n"
"  CTN += 1;\n"
"}\n"
"\n"
"fn __alloc(n: usize) -> *u8 {\n"
"  if n <= 64 {\n"
"    if FL0 != 0 {\n"
"      let h: usize = FL0;\n"
"      FL0 = intrinsics.load_u64((h + 16) as *u8) as usize;\n"
"      zero_bytes(h + 24, 40);\n"
"      return h as *u8;\n"
"    }\n"
"    if C0 == E0 {\n"
"      let chunk: usize = bump_big(16777216) as usize;\n"
"      as_note_chunk(chunk, chunk + 16777216, 0);\n"
"      LO0 = chunk;\n"
"      HI0 = chunk + 16777216;\n"
"      C0 = chunk + 64;\n"
"      E0 = chunk + 16777216;\n"
"      zero_bytes(chunk + 24, 40);\n"
"      return chunk as *u8;\n"
"    }\n"
"    let h2: usize = C0;\n"
"    C0 = C0 + 64;\n"
"    zero_bytes(h2 + 24, 40);\n"
"    return h2 as *u8;\n"
"  }\n"
"  if n <= 128 {\n"
"    if FL1 != 0 {\n"
"      let h3: usize = FL1;\n"
"      FL1 = intrinsics.load_u64((h3 + 16) as *u8) as usize;\n"
"      zero_bytes(h3 + 24, 104);\n"
"      return h3 as *u8;\n"
"    }\n"
"    if C1 == E1 {\n"
"      let chunk: usize = bump_big(16777216) as usize;\n"
"      as_note_chunk(chunk, chunk + 16777216, 1);\n"
"      LO1 = chunk;\n"
"      HI1 = chunk + 16777216;\n"
"      C1 = chunk + 128;\n"
"      E1 = chunk + 16777216;\n"
"      zero_bytes(chunk + 24, 104);\n"
"      return chunk as *u8;\n"
"    }\n"
"    let h4: usize = C1;\n"
"    C1 = C1 + 128;\n"
"    zero_bytes(h4 + 24, 104);\n"
"    return h4 as *u8;\n"
"  }\n"
"  if n <= 256 {\n"
"    if FL2 != 0 {\n"
"      let h5: usize = FL2;\n"
"      FL2 = intrinsics.load_u64((h5 + 16) as *u8) as usize;\n"
"      zero_bytes(h5 + 24, 232);\n"
"      return h5 as *u8;\n"
"    }\n"
"    if C2 == E2 {\n"
"      let chunk: usize = bump_big(16777216) as usize;\n"
"      as_note_chunk(chunk, chunk + 16777216, 2);\n"
"      LO2 = chunk;\n"
"      HI2 = chunk + 16777216;\n"
"      C2 = chunk + 256;\n"
"      E2 = chunk + 16777216;\n"
"      zero_bytes(chunk + 24, 232);\n"
"      return chunk as *u8;\n"
"    }\n"
"    let h6: usize = C2;\n"
"    C2 = C2 + 256;\n"
"    zero_bytes(h6 + 24, 232);\n"
"    return h6 as *u8;\n"
"  }\n"
"  if n <= 512 {\n"
"    if FL3 != 0 {\n"
"      let h7: usize = FL3;\n"
"      FL3 = intrinsics.load_u64((h7 + 16) as *u8) as usize;\n"
"      zero_bytes(h7 + 24, 488);\n"
"      return h7 as *u8;\n"
"    }\n"
"    if C3 == E3 {\n"
"      let chunk: usize = bump_big(16777216) as usize;\n"
"      as_note_chunk(chunk, chunk + 16777216, 3);\n"
"      LO3 = chunk;\n"
"      HI3 = chunk + 16777216;\n"
"      C3 = chunk + 512;\n"
"      E3 = chunk + 16777216;\n"
"      zero_bytes(chunk + 24, 488);\n"
"      return chunk as *u8;\n"
"    }\n"
"    let h8: usize = C3;\n"
"    C3 = C3 + 512;\n"
"    zero_bytes(h8 + 24, 488);\n"
"    return h8 as *u8;\n"
"  }\n"
"  if n <= 1024 {\n"
"    if FL4 != 0 {\n"
"      let h9: usize = FL4;\n"
"      FL4 = intrinsics.load_u64((h9 + 16) as *u8) as usize;\n"
"      zero_bytes(h9 + 24, 1000);\n"
"      return h9 as *u8;\n"
"    }\n"
"    if C4 == E4 {\n"
"      let chunk: usize = bump_big(16777216) as usize;\n"
"      as_note_chunk(chunk, chunk + 16777216, 4);\n"
"      LO4 = chunk;\n"
"      HI4 = chunk + 16777216;\n"
"      C4 = chunk + 1024;\n"
"      E4 = chunk + 16777216;\n"
"      zero_bytes(chunk + 24, 1000);\n"
"      return chunk as *u8;\n"
"    }\n"
"    let h10: usize = C4;\n"
"    C4 = C4 + 1024;\n"
"    zero_bytes(h10 + 24, 1000);\n"
"    return h10 as *u8;\n"
"  }\n"
"  if n <= 4096 {\n"
"    if FL5 != 0 {\n"
"      let h11: usize = FL5;\n"
"      FL5 = intrinsics.load_u64((h11 + 16) as *u8) as usize;\n"
"      zero_bytes(h11 + 24, 4072);\n"
"      return h11 as *u8;\n"
"    }\n"
"    if C5 == E5 {\n"
"      let chunk: usize = bump_big(16777216) as usize;\n"
"      as_note_chunk(chunk, chunk + 16777216, 5);\n"
"      LO5 = chunk;\n"
"      HI5 = chunk + 16777216;\n"
"      C5 = chunk + 4096;\n"
"      E5 = chunk + 16777216;\n"
"      zero_bytes(chunk + 24, 4072);\n"
"      return chunk as *u8;\n"
"    }\n"
"    let h12: usize = C5;\n"
"    C5 = C5 + 4096;\n"
"    zero_bytes(h12 + 24, 4072);\n"
"    return h12 as *u8;\n"
"  }\n"
"  if n <= 4194304 {\n"
"    bcx_ensure();\n"
"    let k: usize = big_class_of(n);\n"
"    let j: usize = k - 6;\n"
"    let stride: usize = as_class_stride(k);\n"
"    let head: usize = intrinsics.load_u64((BCX + j * 8) as *u8) as usize;\n"
"    if head != 0 {\n"
"      intrinsics.store_u64((BCX + j * 8) as *u8,\n"
"                           intrinsics.load_u64((head + 16) as *u8));\n"
"      zero_bytes(head + 24, stride - 24);\n"
"      return head as *u8;\n"
"    }\n"
"    let mut cur: usize = intrinsics.load_u64((BCX + 80 + j * 8) as *u8) as usize;\n"
"    let endr: usize = intrinsics.load_u64((BCX + 160 + j * 8) as *u8) as usize;\n"
"    if cur == endr {\n"
"      let mut want: usize = 16777216;\n"
"      if stride * 8 > want {\n"
"        want = stride * 8;\n"
"      }\n"
"      let chunk: usize = bump_big(want) as usize;\n"
"      as_note_chunk(chunk, chunk + want, k);\n"
"      intrinsics.store_u64((BCX + 240 + j * 8) as *u8, chunk as u64);\n"
"      intrinsics.store_u64((BCX + 320 + j * 8) as *u8, (chunk + want) as u64);\n"
"      intrinsics.store_u64((BCX + 80 + j * 8) as *u8, (chunk + stride) as u64);\n"
"      intrinsics.store_u64((BCX + 160 + j * 8) as *u8, (chunk + want) as u64);\n"
"      cur = chunk + stride;\n"
"      zero_bytes(chunk + 24, stride - 24);\n"
"      return chunk as *u8;\n"
"    }\n"
"    intrinsics.store_u64((BCX + 80 + j * 8) as *u8, (cur + stride) as u64);\n"
"    zero_bytes(cur + 24, stride - 24);\n"
"    return cur as *u8;\n"
"  }\n"
"  return bump_big(n);\n"
"}\n"
"\n"
"static mut BADFREE: usize = 0;\n"
"\n"
"fn __free(p: *u8) {\n"
"  let a: usize = p as usize;\n"
"  if intrinsics.load_u64(a as *u8) == dead_mark() {\n"
"    return;\n"
"  }\n"
"  // the release path frees only after its dec brought the count to zero;\n"
"  // a nonzero count here means a stale owner released a block that has\n"
"  // since been reused — refuse it (a leak, never a corruption) and say so\n"
"  if intrinsics.load_u64(a as *u8) != 0 {\n"
"    BADFREE += 1;\n"
"    if BADFREE < 8 {\n"
"      __eprint_str(__cat3(\"BADFREE a=\", __fmt_u64(a as u64), \" rc=\"));\n"
"      __eprint_str(__cat3(\"\", __fmt_u64(intrinsics.load_u64(a as *u8)), \"\\n\"));\n"
"    }\n"
"    return;\n"
"  }\n"
"  if a >= LO0 && a < HI0 && (a - LO0) % 64 == 0 {\n"
"    intrinsics.store_u64((a + 16) as *u8, FL0 as u64);\n"
"    intrinsics.store_u64(a as *u8, dead_mark() as u64);\n"
"    FL0 = a;\n"
"    return;\n"
"  }\n"
"  if a >= LO1 && a < HI1 && (a - LO1) % 128 == 0 {\n"
"    intrinsics.store_u64((a + 16) as *u8, FL1 as u64);\n"
"    intrinsics.store_u64(a as *u8, dead_mark() as u64);\n"
"    FL1 = a;\n"
"    return;\n"
"  }\n"
"  if a >= LO2 && a < HI2 && (a - LO2) % 256 == 0 {\n"
"    intrinsics.store_u64((a + 16) as *u8, FL2 as u64);\n"
"    intrinsics.store_u64(a as *u8, dead_mark() as u64);\n"
"    FL2 = a;\n"
"    return;\n"
"  }\n"
"  if a >= LO3 && a < HI3 && (a - LO3) % 512 == 0 {\n"
"    intrinsics.store_u64((a + 16) as *u8, FL3 as u64);\n"
"    intrinsics.store_u64(a as *u8, dead_mark() as u64);\n"
"    FL3 = a;\n"
"    return;\n"
"  }\n"
"  if a >= LO4 && a < HI4 && (a - LO4) % 1024 == 0 {\n"
"    intrinsics.store_u64((a + 16) as *u8, FL4 as u64);\n"
"    intrinsics.store_u64(a as *u8, dead_mark() as u64);\n"
"    FL4 = a;\n"
"    return;\n"
"  }\n"
"  if a >= LO5 && a < HI5 && (a - LO5) % 4096 == 0 {\n"
"    intrinsics.store_u64((a + 16) as *u8, FL5 as u64);\n"
"    intrinsics.store_u64(a as *u8, dead_mark() as u64);\n"
"    FL5 = a;\n"
"    return;\n"
"  }\n"
"  // big classes: the current chunk per class lives in the BCX lo/hi pair\n"
"  if BCX != 0 {\n"
"    let mut j: usize = 0;\n"
"    while j < 10 {\n"
"      let blo: usize = intrinsics.load_u64((BCX + 240 + j * 8) as *u8) as usize;\n"
"      let bhi: usize = intrinsics.load_u64((BCX + 320 + j * 8) as *u8) as usize;\n"
"      if a >= blo && a < bhi {\n"
"        let s2: usize = as_class_stride(j + 6);\n"
"        if (a - blo) % s2 == 0 {\n"
"          intrinsics.store_u64((a + 16) as *u8,\n"
"                               intrinsics.load_u64((BCX + j * 8) as *u8));\n"
"          intrinsics.store_u64(a as *u8, dead_mark() as u64);\n"
"          intrinsics.store_u64((BCX + j * 8) as *u8, a as u64);\n"
"          return;\n"
"        }\n"
"      }\n"
"      j += 1;\n"
"    }\n"
"  }\n"
"  // exhausted chunks: the block's chunk is in the registry, not in LO/HI\n"
"  let mut t: usize = 0;\n"
"  while t < CTN {\n"
"    let base: usize = intrinsics.load_u64((CT + t * 24) as *u8) as usize;\n"
"    let hi: usize = intrinsics.load_u64((CT + t * 24 + 8) as *u8) as usize;\n"
"    if a >= base && a < hi {\n"
"      let k: usize = intrinsics.load_u64((CT + t * 24 + 16) as *u8) as usize;\n"
"      let s: usize = as_class_stride(k);\n"
"      if (a - base) % s == 0 {\n"
"        if k == 0 {\n"
"          intrinsics.store_u64((a + 16) as *u8, FL0 as u64);\n"
"          intrinsics.store_u64(a as *u8, dead_mark() as u64);\n"
"          FL0 = a;\n"
"          return;\n"
"        }\n"
"        if k == 1 {\n"
"          intrinsics.store_u64((a + 16) as *u8, FL1 as u64);\n"
"          intrinsics.store_u64(a as *u8, dead_mark() as u64);\n"
"          FL1 = a;\n"
"          return;\n"
"        }\n"
"        if k == 2 {\n"
"          intrinsics.store_u64((a + 16) as *u8, FL2 as u64);\n"
"          intrinsics.store_u64(a as *u8, dead_mark() as u64);\n"
"          FL2 = a;\n"
"          return;\n"
"        }\n"
"        if k == 3 {\n"
"          intrinsics.store_u64((a + 16) as *u8, FL3 as u64);\n"
"          intrinsics.store_u64(a as *u8, dead_mark() as u64);\n"
"          FL3 = a;\n"
"          return;\n"
"        }\n"
"        if k == 4 {\n"
"          intrinsics.store_u64((a + 16) as *u8, FL4 as u64);\n"
"          intrinsics.store_u64(a as *u8, dead_mark() as u64);\n"
"          FL4 = a;\n"
"          return;\n"
"        }\n"
"        if k == 5 {\n"
"          intrinsics.store_u64((a + 16) as *u8, FL5 as u64);\n"
"          intrinsics.store_u64(a as *u8, dead_mark() as u64);\n"
"          FL5 = a;\n"
"          return;\n"
"        }\n"
"        // big class: push onto its BCX freelist (BCX is live — the class\n"
"        // carved a chunk through bcx_ensure before this block existed)\n"
"        let bj: usize = k - 6;\n"
"        intrinsics.store_u64((a + 16) as *u8,\n"
"                             intrinsics.load_u64((BCX + bj * 8) as *u8));\n"
"        intrinsics.store_u64(a as *u8, dead_mark() as u64);\n"
"        intrinsics.store_u64((BCX + bj * 8) as *u8, a as u64);\n"
"        return;\n"
"      }\n"
"    }\n"
"    t += 1;\n"
"  }\n"
"}\n"
"\n"
"fn __fl_count6(head: usize) -> usize {\n"
"  let mut n: usize = 0;\n"
"  let mut p: usize = head;\n"
"  while p != 0 {\n"
"    n += 1;\n"
"    p = intrinsics.load_u64((p + 16) as *u8) as usize;\n"
"  }\n"
"  return n;\n"
"}\n"
"\n"
"fn __alloc_dbg() -> usize {\n"
"  return __fl_count6(FL0) * 64 + __fl_count6(FL1) * 128 + __fl_count6(FL2) * 256\n"
"       + __fl_count6(FL3) * 512 + __fl_count6(FL4) * 1024 + __fl_count6(FL5) * 4096;\n"
"}\n"
"\n"
"fn __heap_ptr() -> usize {\n"
"  return HEAP;\n"
"}\n"
"\n"
"\n"
"// TEMP instrumentation (strip before release): walk every bucket freelist\n"
"// and report how many blocks are parked — carved minus parked minus the\n"
"// per-class residue is the live estimate\n"
"fn __print_str(s: string) {\n"
"  let iov = new Iov { p: (s.ptr as usize) as i32, l: s.len as i32 };\n"
"  let nw = new Iov { p: 0, l: 0 };\n"
"  fd_write(1, iov as usize as i32, 1, nw as usize as i32);\n"
"}\n"
"\n"
"fn __eprint_str(s: string) {\n"
"  let iov = new Iov { p: (s.ptr as usize) as i32, l: s.len as i32 };\n"
"  let nw = new Iov { p: 0, l: 0 };\n"
"  fd_write(2, iov as usize as i32, 1, nw as usize as i32);\n"
"}\n"
"\n"
"fn __exit(code: i32) {\n"
"  proc_exit(code);\n"
"}\n"
"\n"
"// ---- toolchain host hooks (0.3.x): args + file io over raw wasi ----------\n"
"// The self-hosted compiler body calls these per-target hooks; this tail\n"
"// implements them over wasi_snapshot_preview1. fd 3 is the preopened\n"
"// working directory wasmtime hands the guest.\n"
"\n"
"extern fn args_sizes_get(count: i32, buf: i32) -> i32;\n"
"extern fn args_get(argv: i32, buf: i32) -> i32;\n"
"extern fn path_open(fd: i32, dirflags: i32, path: i32, path_len: i32,\n"
"                    oflags: i32, rights_base: u64, rights_inheriting: u64,\n"
"                    fdflags: i32, opened: i32) -> i32;\n"
"extern fn fd_read(fd: i32, iovs: i32, iovs_len: i32, nread: i32) -> i32;\n"
"extern fn fd_close(fd: i32) -> i32;\n"
"// wasmtime 40's preview1 adapter takes the two-directory form:\n"
"// (old_fd, old_path, old_len, new_fd, new_path, new_len)\n"
"extern fn path_rename(old_fd: i32, old_path: i32, old_path_len: i32,\n"
"                      new_fd: i32, new_path: i32, new_path_len: i32) -> i32;\n"
"\n"
"fn __c_len(p: *u8) -> i32 {\n"
"  let mut n: i32 = 0;\n"
"  loop {\n"
"    if intrinsics.load_u8(((p as usize) + (n as usize)) as *u8) == 0 {\n"
"      break;\n"
"    }\n"
"    n += 1;\n"
"  }\n"
"  return n;\n"
"}\n"
"\n"
"// flags: 0 = read-only, nonzero = create/truncate + write\n"
"fn __open(path: *u8, flags: i32, mode: i32) -> i32 {\n"
"  let plen: i32 = __c_len(path);\n"
"  let mut oflags: i32 = 0;\n"
"  let mut rights: u64 = 2; // FD_READ\n"
"  if flags != 0 {\n"
"    oflags = 1 | 8; // CREAT | TRUNC\n"
"    rights = (2 | 4) as u64; // FD_READ | FD_WRITE\n"
"  }\n"
"  let out: *u8 = __alloc(4);\n"
"  let err: i32 = path_open(3, 0, path as usize as i32, plen, oflags,\n"
"                           rights, rights, 0, out as usize as i32);\n"
"  if err != 0 {\n"
"    return -1;\n"
"  }\n"
"  return intrinsics.load_u64(out) as i32;\n"
"}\n"
"\n"
"fn __read(fd: i32, buf: *u8, n: usize) -> isize {\n"
"  let iov = new Iov { p: buf as usize as i32, l: n as i32 };\n"
"  let nr = new Iov { p: 0, l: 0 };\n"
"  if fd_read(fd, iov as usize as i32, 1, nr as usize as i32) != 0 {\n"
"    return -1;\n"
"  }\n"
"  // the out-param address IS &nr (the struct base): the count lands in .p\n"
"  return nr.p as isize;\n"
"}\n"
"\n"
"// one line from stdin, the newline stripped; \"\" at EOF. Byte-at-a-time so\n"
"// the reader never consumes past the line — a following read_line continues\n"
"// exactly where this one stopped\n"
"fn read_line() -> string {\n"
"  let mut buf: []u8 = make([]u8, 128);\n"
"  let mut n: usize = 0;\n"
"  loop {\n"
"    if n + 1 >= len(buf) {\n"
"      let grown: []u8 = make([]u8, len(buf) * 2);\n"
"      let mut k: usize = 0;\n"
"      while k < n {\n"
"        grown[k] = buf[k];\n"
"        k += 1;\n"
"      }\n"
"      buf = grown;\n"
"    }\n"
"    if __read(0, ((buf.ptr as usize) + n) as *u8, 1) <= 0 {\n"
"      break;\n"
"    }\n"
"    if buf[n] == 10 {\n"
"      break;\n"
"    }\n"
"    n += 1;\n"
"  }\n"
"  return intrinsics.slice_string(buf[0..n]);\n"
"}\n"
"\n"
"fn __write(fd: i32, buf: *u8, n: usize) -> isize {\n"
"  let iov = new Iov { p: buf as usize as i32, l: n as i32 };\n"
"  let nw = new Iov { p: 0, l: 0 };\n"
"  if fd_write(fd, iov as usize as i32, 1, nw as usize as i32) != 0 {\n"
"    return -1;\n"
"  }\n"
"  // the out-param address IS &nw (the struct base): the count lands in .p\n"
"  return nw.p as isize;\n"
"}\n"
"\n"
"fn __close(fd: i32) -> i32 {\n"
"  return fd_close(fd);\n"
"}\n"
"\n"
"// tmp+rename keeps every write on a fresh path; over WASI it rides the\n"
"// preopened cwd (fd 3), so both paths must be relative to it\n"
"fn __rename(old_path: *u8, new_path: *u8) -> i32 {\n"
"  return path_rename(3, old_path as usize as i32, __c_len(old_path),\n"
"                     3, new_path as usize as i32, __c_len(new_path));\n"
"}\n"
"\n"
"fn __can_spawn() -> bool {\n"
"  return false;\n"
"}\n"
"\n"
"fn __program_args() -> []string {\n"
"  let info: *u8 = __alloc(8); // [count: i32][bufsize: i32]\n"
"  if args_sizes_get(info as usize as i32, ((info as usize) + 4) as i32) != 0 {\n"
"    return make([]string, 0);\n"
"  }\n"
"  let count: usize = intrinsics.load_u32(info) as usize;\n"
"  let bufsize: usize = intrinsics.load_u32(((info as usize) + 4) as *u8) as usize;\n"
"  if count == 0 {\n"
"    return make([]string, 0);\n"
"  }\n"
"  let argv: *u8 = __alloc(count * 4 + 8);\n"
"  let buf: *u8 = __alloc(bufsize + 8);\n"
"  if args_get(argv as usize as i32, buf as usize as i32) != 0 {\n"
"    return make([]string, 0);\n"
"  }\n"
"  let args: []string = make([]string, count);\n"
"  let mut i: usize = 0;\n"
"  while i < count {\n"
"    let p: usize = intrinsics.load_u32(((argv as usize) + (i * 4)) as *u8) as usize;\n"
"    let n: usize = __c_len(p as *u8) as usize;\n"
"    let raw: []u8 = make([]u8, n);\n"
"    let mut k: usize = 0;\n"
"    while k < n {\n"
"      raw[k] = intrinsics.load_u8(((p as usize) + k) as *u8);\n"
"      k += 1;\n"
"    }\n"
"    args[i] = intrinsics.slice_string(raw);\n"
"    i += 1;\n"
"  }\n"
"  return args;\n"
"}\n";
